import { sha256 } from '@peertube/peertube-node-utils'
import { VIDEO_FILE_TOKEN_LIFETIME } from '../../initializers/constants.js'
import { getValue, setValue } from './redis-client.js'

/**
 * Temporary tokens used as URL query parameters to access video static files.
 *
 * They live in Redis so a token generated by one process is accepted by every other one
 */

export type VideoTokenPayload = {
  videoUUID: string

  userId?: number

  // Session that generated this token, so revoking the other sessions of the user keeps it
  accessTokenHash?: string

  // Timestamp in milliseconds, so a process can keep the resolved token in memory until it expires
  expires: number

  // TODO: Remove `?` in v10
  createdAt?: number
}

export function setVideoToken (token: string, payload: VideoTokenPayload) {
  const ttl = getVideoTokenTTL(payload.expires)
  if (ttl <= 0) throw new Error('Cannot store an expired video token')

  return setValue(generateVideoTokenKey(token), JSON.stringify(payload), ttl)
}

export async function getVideoToken (token: string): Promise<VideoTokenPayload> {
  const value = await getValue(generateVideoTokenKey(token))
  if (!value) return undefined

  try {
    return JSON.parse(value)
  } catch {
    return undefined
  }
}

export type UserVideoTokensRevocation = {
  // Video file tokens of the user generated before this date (timestamp in milliseconds) are invalid...
  revokedAt: number

  // ...except the ones generated by the session the revocation keeps
  keptAccessTokenHash?: string
}

// A new revocation replaces the previous one: sessions it doesn't keep were already deleted by the previous one
export function setUserVideoTokensRevocation (userId: number, revocation: UserVideoTokensRevocation) {
  return setValue(generateUserVideoTokensRevocationKey(userId), JSON.stringify(revocation), VIDEO_FILE_TOKEN_LIFETIME)
}

export async function getUserVideoTokensRevocation (userId: number): Promise<UserVideoTokensRevocation> {
  const value = await getValue(generateUserVideoTokensRevocationKey(userId))
  if (!value) return undefined

  try {
    return JSON.parse(value)
  } catch {
    return undefined
  }
}

export function isVideoTokenRevoked (payload: VideoTokenPayload, revocation: UserVideoTokensRevocation) {
  if (!revocation) return false

  const createdAt = payload.createdAt ?? payload.expires - VIDEO_FILE_TOKEN_LIFETIME
  if (createdAt > revocation.revokedAt) return false

  return !revocation.keptAccessTokenHash || payload.accessTokenHash !== revocation.keptAccessTokenHash
}

// Don't store access tokens in Redis, only what is needed to recognize their session
export function hashVideoTokenAccessToken (accessToken: string) {
  if (!accessToken) return undefined

  return sha256(accessToken)
}

// Remaining lifetime of a token in milliseconds, never longer than the lifetime of a new token
export function getVideoTokenTTL (expires: number) {
  return Math.min(expires - Date.now(), VIDEO_FILE_TOKEN_LIFETIME)
}

// ---------------------------------------------------------------------------

function generateVideoTokenKey (token: string) {
  return 'video-token-' + token
}

function generateUserVideoTokensRevocationKey (userId: number) {
  return 'video-tokens-revocation-' + userId
}
